def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x),
                               (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w
                            and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((color, cells))

    panels = []
    panel_cells = set()
    for color, cells in components:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if (len(cells) == 25 and max(rs) - min(rs) == 4
                and max(cs) - min(cs) == 4):
            panel = (color, min(rs), min(cs))
            panels.append(panel)
            panel_cells |= cells

    if not panels:
        return grid

    # Motif cells may form multiple disconnected components, so combine
    # all non-panel pixels of each color before finding the 3x3 pattern.
    by_color = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r, c) not in panel_cells:
                by_color.setdefault(grid[r][c], []).append((r, c))

    motifs = {}
    for color, cells in by_color.items():
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, c0 = min(rs), min(cs)
        if max(rs) - r0 == 2 and max(cs) - c0 == 2:
            motifs[color] = {(r - r0, c - c0) for r, c in cells}

    r0 = max(0, min(r for _, r, _ in panels) - 1)
    c0 = max(0, min(c for _, _, c in panels) - 1)
    r1 = min(h - 1, max(r + 4 for _, r, _ in panels) + 1)
    c1 = min(w - 1, max(c + 4 for _, _, c in panels) + 1)
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    for color, r, c in panels:
        for dr, dc in motifs.get(color, set()):
            out[r + 1 + dr - r0][c + 1 + dc - c0] = bg

    return out
